import { Question } from '@/types/question';

const questions: Question[] = [
  { id: 'ai-engineer-ai-agents-l4-001', language: 'ai-engineer', level: 'level4', category: 'AI Agents & Tool Use', subcategory: 'Planning', question: 'What is the fundamental limitation of ReAct-style agents for long-horizon tasks, and how do planning-based agents (e.g., Plan-and-Execute) address it?', options: ['ReAct agents always produce optimal plans', 'ReAct interleaves reasoning and action greedily (one step at a time), which can lead to getting stuck in suboptimal paths without backtracking. Plan-and-Execute agents first generate a complete high-level plan, then execute each step, allowing plan revision after each step\'s result. This enables global coherence and recovery from failures, but adds latency for plan generation and may generate plans that become invalid as the environment changes', 'ReAct agents always outperform planning-based agents', 'Plan-and-Execute agents never need to revise their plans'], correctAnswer: 1, explanation: 'ReAct: Thought→Action→Observation→Thought... Each step is locally optimal but has no lookahead. For complex tasks (book a trip: search flights → compare → book → hotel → car), ReAct may choose the wrong flight before considering hotel availability. Plan-and-Execute (Wang et al. 2023): Step 1: LLM generates a multi-step plan. Step 2: executor runs each step. Step 3: replanner adjusts remaining steps based on results. Benefits: considers the full task before acting. Costs: planning is expensive (extra LLM call), plans may be wrong (need replanning), and some tasks don\'t decompose well. LangGraph implements this as a state machine with planning/execution/replanning nodes.', tags: ['react', 'plan-and-execute', 'planning', 'long-horizon'] },
  { id: 'ai-engineer-ai-agents-l4-002', language: 'ai-engineer', level: 'level4', category: 'AI Agents & Tool Use', subcategory: 'Multi-Agent', question: 'What are the coordination patterns for multi-agent systems and when does each apply?', options: ['Multi-agent systems always use a single coordinator agent', 'Key patterns: (1) Hierarchical: manager agent delegates to specialist agents (good for task decomposition). (2) Debate/Discussion: agents argue different perspectives, converging on a consensus (good for reasoning quality). (3) Pipeline: agents process sequentially, each refining the previous output (good for multi-stage workflows). (4) Competitive: multiple agents propose solutions, a judge selects the best (good for creative tasks). Each trades coordination overhead for different quality/efficiency benefits', 'All multi-agent patterns produce identical results', 'Multi-agent systems always outperform single agents'], correctAnswer: 1, explanation: 'Hierarchical (AutoGen, CrewAI): CEO agent breaks task into subtasks → delegates to coder, researcher, reviewer agents. Good for complex projects. Debate (Du et al. 2023): 3 agents independently answer, then discuss disagreements for 2-3 rounds → improved factual accuracy. Pipeline (LangGraph): draft → review → edit → finalize, each with a specialized prompt/model. Competitive (AlpacaEval): multiple agents generate responses, a judge agent ranks them. Key decision factors: task complexity (simple → single agent), need for diverse perspectives (reasoning → debate), workflow structure (stages → pipeline), and compute budget (multi-agent uses N× more tokens).', tags: ['multi-agent', 'coordination', 'hierarchical', 'debate'] },
  { id: 'ai-engineer-ai-agents-l4-003', language: 'ai-engineer', level: 'level4', category: 'AI Agents & Tool Use', subcategory: 'Tool Calling', question: 'How should tool schemas be designed to minimize LLM errors in function calling?', options: ['More parameters always lead to better tool calls', 'LLMs never make errors when calling tools', 'Tool schemas have no impact on error rates', 'Effective tool schemas: (1) use descriptive parameter names (not "q" but "search_query"), (2) include clear descriptions with examples in the schema, (3) use enums for constrained parameter values, (4) minimize required parameters (use sensible defaults), (5) return structured outputs with clear field names. Ambiguous schemas cause parameter confusion, type errors, and hallucinated parameters. Testing tool schemas with diverse query patterns before deployment catches most issues'], correctAnswer: 3, explanation: 'Common LLM tool-calling errors: (1) wrong parameter type (string instead of int), (2) hallucinated parameters not in the schema, (3) wrong tool selection (similar-sounding tools), (4) incorrect parameter values (wrong date format). Schema best practices: use JSON Schema with "description" on every parameter, constrain with "enum" where possible, add "examples" in descriptions, keep parameter count low (<5), use "required" sparingly. Testing: create a diverse evaluation set of user queries → run tool calling → check: correct tool selected? correct parameters? valid types? Iterate on schema descriptions based on error patterns. OpenAI/Anthropic function calling docs recommend explicit format specifications in descriptions.', tags: ['tool-schemas', 'function-calling', 'error-reduction', 'api-design'] },
  { id: 'ai-engineer-ai-agents-l4-004', language: 'ai-engineer', level: 'level4', category: 'AI Agents & Tool Use', subcategory: 'State Management', question: 'What is a state machine architecture for LLM agents and why is it more reliable than free-form agent loops?', options: ['A state machine defines explicit states (planning, executing, reviewing, completed) with valid transitions and guards. Unlike free-form loops where the LLM decides what to do next (risking infinite loops, repeated actions, or skipping steps), state machines enforce structure: from "executing" you can only transition to "reviewing" or "error." LangGraph implements this as a graph with conditional edges. This provides predictability, debuggability, and prevents runaway agent behavior', 'Free-form agent loops are always more reliable', 'State machines require coding every possible conversation path', 'State machines prevent agents from being creative'], correctAnswer: 0, explanation: 'Free-form loop risks: (1) infinite loop: agent keeps calling the same tool, (2) action repetition: retrying a failed action identically, (3) path explosion: in complex tasks, the agent wanders. State machine benefits: (1) explicit states with entry/exit conditions, (2) maximum iterations per state, (3) mandatory review states before actions with side effects, (4) error handling states, (5) clear termination conditions. LangGraph: define nodes (LLM calls, tool calls) and edges (conditional routing based on LLM output or state). This is a middle ground between rigid scripts and fully autonomous agents. Production agents (customer service, code generation) almost always use state machines for reliability.', tags: ['state-machine', 'langgraph', 'reliability', 'agent-architecture'] },
  { id: 'ai-engineer-ai-agents-l4-005', language: 'ai-engineer', level: 'level4', category: 'AI Agents & Tool Use', subcategory: 'Evaluation', question: 'How should LLM agents be evaluated and what makes agent evaluation harder than standard LLM evaluation?', options: ['Agent evaluation is simpler than LLM evaluation', 'Agent evaluation uses the same metrics as standard LLM benchmarks', 'Agent evaluation must assess: (1) task completion rate (did it achieve the goal?), (2) efficiency (how many steps/tokens/tools used?), (3) tool usage correctness (right tools, right parameters?), (4) error recovery (did it handle failures gracefully?), (5) safety (did it avoid harmful actions?). Unlike static Q&A evaluation, agents interact with environments that have stochastic outcomes, making results non-deterministic. Evaluation requires sandboxed environments and multi-trial averaging', 'Agents only need to be evaluated on final output quality'], correctAnswer: 2, explanation: 'Agent evaluation challenges: (1) Non-determinism: same agent may take different paths → need multiple trials per task, (2) Environment interaction: need sandboxed tools (mock APIs, test databases) for safe evaluation, (3) Multi-dimensional: task success, efficiency, safety, cost are all relevant, (4) Trajectory evaluation: intermediate steps matter (did it use the right approach?), (5) Ground truth is expensive (human evaluation of full trajectories). Benchmarks: SWE-bench (code agents), WebArena (web navigation), GAIA (general assistant). Metrics: pass@1 (single attempt success), pass@k (success in k attempts), cost per successful task, average tool calls per task. Evaluation frameworks: AgentBench, TAU-bench.', tags: ['agent-evaluation', 'benchmarks', 'trajectory', 'sandboxed-testing'] },
  { id: 'ai-engineer-ai-agents-l4-006', language: 'ai-engineer', level: 'level4', category: 'AI Agents & Tool Use', subcategory: 'Code Generation', question: 'What is the code interpreter pattern for LLM agents and what safety considerations does it raise?', options: ['Code interpreter agents generate and execute Python code to solve problems (data analysis, math, visualization). Safety considerations: (1) sandboxing execution environment (Docker/gVisor to prevent filesystem/network access), (2) resource limits (CPU time, memory to prevent DoS), (3) disabling dangerous modules (os.system, subprocess, network), (4) output sanitization (preventing data exfiltration through generated plots/files). The pattern is powerful because code provides exact computation that LLMs struggle with, but requires careful isolation', 'Code interpreters should have full system access for maximum capability', 'Sandboxing eliminates all security risks', 'Code interpreters execute code without any safety concerns'], correctAnswer: 0, explanation: 'Code interpreter: LLM generates Python → executes in sandbox → returns output (text, plots, files) → LLM interprets results → generates more code if needed. Safety: (1) Process isolation: Docker container with no network, read-only filesystem, limited CPU/memory, (2) Module restrictions: whitelist allowed imports (numpy, pandas, matplotlib — not os, subprocess, socket), (3) Execution timeout: kill after 30 seconds, (4) Output limits: cap output size to prevent memory exhaustion, (5) Stateless execution: each code block runs in a fresh environment (or carefully managed state). OpenAI Code Interpreter, E2B, and Modal provide managed sandboxed execution. For self-hosted: Jupyter kernels in Docker with seccomp profiles.', tags: ['code-interpreter', 'sandboxing', 'safety', 'execution'] },
  { id: 'ai-engineer-ai-agents-l4-007', language: 'ai-engineer', level: 'level4', category: 'AI Agents & Tool Use', subcategory: 'Memory', question: 'What is the difference between episodic and semantic memory in agent systems?', options: ['Episodic and semantic memory are identical', 'Episodic memory stores specific past experiences (full conversation logs, action-outcome pairs from previous tasks). Semantic memory stores general knowledge extracted from experiences (user preferences, learned facts, tool usage patterns). Episodic memory enables learning from specific past successes/failures; semantic memory enables generalization. Agents should extract semantic knowledge from episodic memories over time, similar to human memory consolidation', 'Agents only need episodic memory', 'Semantic memory stores raw conversation transcripts'], correctAnswer: 1, explanation: 'Episodic: "Last Tuesday, the user asked about flight prices to Paris. I used the flights_search tool with departure_date=2024-03-15 and found $450 roundtrip." Semantic: "User prefers direct flights, budget range $300-600, usually travels in March." Episodic → retrieval: find past similar situations and reuse strategies. Semantic → generalization: apply learned patterns to new situations. Memory consolidation: periodically process episodic memories → extract semantic facts → store in structured format (key-value pairs or knowledge graph). This mirrors human memory: hippocampus (episodic) → cortex (semantic) during sleep. MemGPT and Letta implement both memory types with LLM-managed storage/retrieval.', tags: ['episodic-memory', 'semantic-memory', 'memory-consolidation', 'agent-memory'] },
  { id: 'ai-engineer-ai-agents-l4-008', language: 'ai-engineer', level: 'level4', category: 'AI Agents & Tool Use', subcategory: 'Orchestration', question: 'What are the key differences between LangChain, LlamaIndex, and CrewAI for building agent applications?', options: ['All agent frameworks are identical', 'LangChain is the only framework capable of building agents', 'Framework choice has no impact on agent quality', 'LangChain: general-purpose chain/agent framework with extensive tool integrations and LangGraph for complex agent workflows. LlamaIndex: specialized for data-connected agents (RAG, structured data querying) with superior document processing. CrewAI: focused on multi-agent collaboration with role-based agents and task delegation. Choose based on use case: RAG-heavy → LlamaIndex, complex workflows → LangChain/LangGraph, multi-agent → CrewAI. All can be combined as they address different layers of the stack'], correctAnswer: 3, explanation: 'LangChain: broad ecosystem (100+ integrations), LCEL for composable chains, LangGraph for stateful multi-actor workflows (state machines, human-in-the-loop). Strength: flexibility and breadth. LlamaIndex: ingestion → indexing → querying pipeline, excellent for knowledge-intensive agents (query engines, sub-question decomposition, agentic RAG). Strength: structured data interaction. CrewAI: define agents with roles/goals/backstories, tasks with expected outputs, process (sequential/hierarchical). Strength: multi-agent collaboration out of the box. Emerging: AutoGen (Microsoft) for conversable agents, Semantic Kernel for enterprise. Practical advice: start with the simplest approach (direct API calls), add framework when complexity warrants it.', tags: ['langchain', 'llamaindex', 'crewai', 'agent-frameworks'] },
  { id: 'ai-engineer-ai-agents-l4-009', language: 'ai-engineer', level: 'level4', category: 'AI Agents & Tool Use', subcategory: 'Human-in-the-Loop', question: 'When and how should human oversight be integrated into agent workflows?', options: ['Human-in-the-loop should be integrated at: (1) high-stakes decision points (before financial transactions, sending emails, modifying databases), (2) low-confidence situations (when the agent is uncertain about the correct action), (3) novel scenarios (tasks outside the agent\'s known capabilities), (4) periodic audits (sampling agent actions for quality review). Implementation: interrupt the agent loop, present the proposed action to a human for approval/modification, then continue. This balances automation efficiency with safety', 'Humans should approve every single agent action', 'Human oversight slows down agents without any benefit', 'Human oversight is never needed for agent systems'], correctAnswer: 0, explanation: 'Human-in-the-loop patterns: (1) Approval gate: before irreversible actions (send email, execute trade, deploy code), pause and request human approval. LangGraph supports this with interrupt_before on specific nodes. (2) Escalation: when confidence < threshold or after N failed attempts, escalate to human. (3) Review queue: agent handles routine tasks autonomously, queues edge cases for human review. (4) Correction learning: human corrections are fed back to improve the agent (fine-tuning, prompt updates). Implementation: store agent state → present to human UI → human approves/modifies → resume agent with updated state. Critical for: customer-facing agents, financial operations, code deployment, medical/legal domains.', tags: ['human-in-the-loop', 'oversight', 'approval-gate', 'escalation'] },
  { id: 'ai-engineer-ai-agents-l4-010', language: 'ai-engineer', level: 'level4', category: 'AI Agents & Tool Use', subcategory: 'Tool Discovery', question: 'What is the tool discovery problem for agents with access to many tools, and how is it solved?', options: ['Agents work equally well with 5 or 5000 tools', 'When an agent has access to hundreds of tools, including all tool schemas in the prompt is infeasible (token limit) and confusing (too many options). Tool discovery solutions: (1) embed tool descriptions and retrieve relevant tools based on the user query, (2) hierarchical tool organization (categories → specific tools), (3) few-shot examples showing when to use each tool, (4) a "tool selector" LLM call that picks relevant tools before the main agent call. This reduces the effective tool set to 5-10 per query', 'Tool discovery is only needed for agents with more than 1000 tools', 'Including all tool schemas in every prompt is the best approach'], correctAnswer: 1, explanation: 'Problem: 200 tools × 200 tokens per schema = 40K tokens just for tool definitions. The LLM struggles to select among many similar tools. Solutions: (1) Semantic tool retrieval: embed tool descriptions → for each user query, retrieve top-5 relevant tools → include only those in the prompt. (2) Tool categories: first classify query into category (search, email, calendar, code) → include only that category\'s tools. (3) Multi-step: first call with all tool names (no params) → LLM picks 3-5 → second call with full schemas of selected tools. (4) Tool documentation RAG: when the LLM is unsure about parameters, it can search tool documentation. Gorilla (Patil et al. 2023) showed that tool retrieval + LLM achieves better tool accuracy than providing all tools.', tags: ['tool-discovery', 'tool-retrieval', 'many-tools', 'semantic-routing'] },
  { id: 'ai-engineer-ai-agents-l4-011', language: 'ai-engineer', level: 'level4', category: 'AI Agents & Tool Use', subcategory: 'Error Recovery', question: 'What error recovery strategies should agents implement when tool calls fail?', options: ['Error recovery is unnecessary for production agents', 'Agents should retry the same failing action indefinitely', 'Effective error recovery: (1) retry with backoff for transient errors (network timeouts, rate limits), (2) reformulate the request (rephrase search query, adjust parameters) for semantic failures, (3) try alternative tools (use a different search engine or API), (4) decompose the failing step into smaller sub-steps, (5) ask the user for clarification when input is ambiguous, (6) graceful degradation (return partial results with explanation). Each strategy should have a maximum retry count to prevent infinite loops', 'Agents should stop execution when any tool call fails'], correctAnswer: 2, explanation: 'Error taxonomy and responses: (1) Transient (HTTP 429/503): retry with exponential backoff, max 3 attempts, (2) Authentication: alert user, cannot self-fix, (3) Invalid parameters: the agent should analyze the error message, adjust parameters, retry (e.g., date format wrong → reformat), (4) No results: reformulate query (broader search terms, different keywords), (5) Tool unavailable: fall back to alternative tool or inform user. Implementation in LangGraph: error handling nodes that classify the error type and route to appropriate recovery strategy. Key principle: the agent should use the error message as context for its next reasoning step, not just blindly retry. Logging all errors and recovery attempts is essential for improving the system over time.', tags: ['error-recovery', 'retry', 'fallback', 'graceful-degradation'] },
  { id: 'ai-engineer-ai-agents-l4-012', language: 'ai-engineer', level: 'level4', category: 'AI Agents & Tool Use', subcategory: 'MCP', question: 'What is the Model Context Protocol (MCP) and how does it standardize tool integration for agents?', options: ['MCP is a model training protocol', 'MCP is an open protocol for connecting LLM applications to external data sources and tools through a standardized interface. It defines a client-server architecture where MCP servers expose tools, resources (data), and prompts, and MCP clients (agent frameworks) consume them. This standardization allows any MCP-compatible agent to use any MCP-compatible tool without custom integration code, similar to how HTTP standardized web communication', 'MCP is proprietary to a single AI company', 'MCP replaces the need for tool descriptions in prompts'], correctAnswer: 1, explanation: 'MCP (Anthropic 2024): defines JSON-RPC based protocol for: (1) Tools: functions the LLM can invoke (search, database query, etc.), with JSON Schema parameter definitions, (2) Resources: data the LLM can read (files, database records, API responses), (3) Prompts: reusable prompt templates. Architecture: MCP Host (agent app) → MCP Client → MCP Server (exposes tools). Benefits: write a tool server once (e.g., GitHub MCP server), any compatible agent can use it. Growing ecosystem: Slack, GitHub, Google Drive, database MCP servers. Enables composable agent tooling without framework lock-in. Supported by Claude, Cursor, Windsurf, and other agent platforms.', tags: ['mcp', 'model-context-protocol', 'tool-standardization', 'interoperability'] },
  { id: 'ai-engineer-ai-agents-l4-013', language: 'ai-engineer', level: 'level4', category: 'AI Agents & Tool Use', subcategory: 'Reflection', question: 'What is the Reflexion pattern for self-improving agents?', options: ['Reflexion adds a reflection step after task completion: the agent evaluates its own trajectory (what went well, what went wrong), generates verbal feedback, and stores it in a persistent memory. On subsequent similar tasks, the agent retrieves and uses this self-reflection to avoid repeating mistakes. This creates a self-improvement loop within an episode without gradient-based learning, achieving significant performance gains on coding and reasoning benchmarks', 'Self-reflection always improves agent performance', 'Reflexion requires retraining the agent model', 'Reflexion simply retries failed actions without learning'], correctAnswer: 0, explanation: 'Reflexion (Shinn et al. 2023): (1) Agent attempts task → gets result, (2) Evaluator scores the result (automated test, self-evaluation), (3) If failed: Self-reflection step — "I failed because I used the wrong API endpoint. Next time I should check the documentation first." (4) Store reflection in memory, (5) Retry task with reflection as additional context. On HumanEval (code generation): 68% → 91% accuracy with Reflexion. Key: the reflection must be specific and actionable, not generic ("I should try harder"). Limitations: the agent must be able to evaluate its own output (needs automated tests or a judge), and reflection quality depends on the LLM\'s self-awareness. Works best when the agent has multiple attempts and clear success criteria.', tags: ['reflexion', 'self-improvement', 'reflection', 'verbal-feedback'] },
  { id: 'ai-engineer-ai-agents-l4-014', language: 'ai-engineer', level: 'level4', category: 'AI Agents & Tool Use', subcategory: 'Structured Output', question: 'How do agents maintain structured state across multi-turn interactions?', options: ['Agents do not need to maintain state between turns', 'Agents use structured state objects (Pydantic models, TypedDicts) that persist across turns and are updated after each action. The state includes: current plan, completed steps, gathered information, pending decisions, and error history. LangGraph defines state as a typed graph state that flows between nodes, with reducers for state updates. This structured state enables: resumability (restart from checkpoint), observability (inspect state at any point), and branching (try multiple approaches from the same state)', 'Raw conversation history is sufficient for agent state', 'State management adds no value to agent systems'], correctAnswer: 1, explanation: 'Agent state management: (1) Define state schema: { plan: List[Step], completed: List[Result], context: Dict, errors: List[Error], iteration: int }, (2) After each agent action, update state (not just append to conversation), (3) State is the source of truth — even if conversation is truncated, state preserves essential information. Benefits: (a) Resumability: serialize state → restart from checkpoint after crash, (b) Debugging: log state at each step → understand exactly what the agent knew when it made each decision, (c) Branching: copy state → try two different approaches → compare results, (d) Human-in-the-loop: show state to human for review. LangGraph: state is a TypedDict passed between graph nodes, with reducer functions defining how concurrent updates are merged.', tags: ['structured-state', 'state-management', 'langgraph', 'checkpointing'] },
  { id: 'ai-engineer-ai-agents-l4-015', language: 'ai-engineer', level: 'level4', category: 'AI Agents & Tool Use', subcategory: 'Web Agents', question: 'What are the key challenges of building web browsing agents and how do modern approaches handle them?', options: ['Web browsing agents are trivial to build with standard LLMs', 'Web agents only need to process HTML text, not visual content', 'Web agents can perfectly navigate any website without errors', 'Key challenges: (1) representing web page state to the LLM (full HTML is too long, screenshots lose interactability), (2) action space is huge (any element can be clicked/typed), (3) pages are dynamic (JavaScript-rendered content), (4) multi-step navigation requires long-term memory. Modern approaches: accessibility tree extraction (structured element list), set-of-marks prompting (numbered visual annotations), and multi-modal agents that combine screenshots with structured element data. Playwright/Selenium provide the action interface'], correctAnswer: 3, explanation: 'Web agent architecture: (1) Observation: extract accessibility tree (DOM elements with roles/labels) + optional screenshot. HTML is 100K+ tokens; accessibility tree is ~5K tokens for most pages. (2) Action space: click(element_id), type(element_id, text), scroll(), navigate(url), wait(). (3) Set-of-Marks (Yang et al. 2023): overlay numbered bounding boxes on screenshot → LLM sees the visual page with numbered interactive elements → outputs "click 14." (4) Memory: maintain visited pages, extracted information, current goal. Challenges: CAPTCHA, login walls, dynamic content loading, pop-ups. Benchmarks: WebArena, Mind2Web. Production: Browserbase, AgentQL provide managed browser infrastructure for agents.', tags: ['web-agents', 'browser-automation', 'accessibility-tree', 'set-of-marks'] },
  { id: 'ai-engineer-ai-agents-l4-016', language: 'ai-engineer', level: 'level4', category: 'AI Agents & Tool Use', subcategory: 'Cost Control', question: 'How can agent token costs be controlled without sacrificing task completion quality?', options: ['Cost control strategies: (1) use smaller models for simple steps (routing, classification) and larger models only for complex reasoning, (2) implement context window management (summarize older history instead of keeping full transcripts), (3) cache tool results to avoid redundant calls, (4) set maximum iteration limits per task, (5) use structured outputs to reduce verbosity, (6) implement early termination when sufficient information is gathered. Token budgeting per task type prevents runaway costs while maintaining quality on valuable tasks', 'Larger models are always more cost-effective for agents', 'Token costs are negligible and do not need management', 'Agent costs cannot be controlled without reducing quality'], correctAnswer: 0, explanation: 'Agent costs compound: each reasoning step + tool description + conversation history → 2K-10K tokens per step × 10-50 steps per task → 20K-500K tokens per task. Cost controls: (1) Model cascade: GPT-4o-mini for tool selection, GPT-4o for complex reasoning → 5-10x cheaper overall, (2) Context compression: after every 5 steps, summarize conversation history to 500 tokens instead of keeping 10K tokens, (3) Tool result truncation: limit tool output to first 2K tokens (most relevant information is at the top), (4) Budget enforcement: set max_tokens_per_task, terminate gracefully when budget is reached, (5) Caching: if the agent calls the same API with the same params, return cached result. Monitoring: track tokens_per_successful_task as a key metric, optimize outliers.', tags: ['cost-control', 'token-budget', 'model-cascade', 'context-compression'] },
  { id: 'ai-engineer-ai-agents-l4-017', language: 'ai-engineer', level: 'level4', category: 'AI Agents & Tool Use', subcategory: 'Grounding', question: 'What is the "grounding" problem in agents and how does tool use help mitigate hallucination?', options: ['Tool use eliminates all hallucination in agents', 'Agents never hallucinate when using tools', 'Grounding is only relevant for chatbots, not agents', 'Grounding means ensuring agent outputs are based on verified external information rather than the LLM\'s parametric memory (which can hallucinate). Tool use helps by: (1) requiring the agent to retrieve facts before making claims, (2) providing verifiable sources for each piece of information, (3) enabling the agent to check its own claims against external data. However, tools themselves can return incorrect information, and the agent can misinterpret tool outputs, so grounding reduces but does not eliminate hallucination'], correctAnswer: 3, explanation: 'The grounding loop: (1) user asks question → (2) agent identifies what information is needed → (3) retrieves from authoritative tools/databases → (4) synthesizes answer from retrieved data with citations. This is more reliable than the LLM generating answers from memory. Remaining risks: (a) agent formulates the wrong query → retrieves irrelevant info → hallucinates based on wrong context, (b) tool returns outdated or incorrect data, (c) agent extrapolates beyond what tools returned ("the database shows revenue was $5M" → agent adds "which represents 20% growth" without data). Mitigation: instruct the agent to distinguish between tool-provided facts and inferences, cite sources, and express uncertainty when information is incomplete.', tags: ['grounding', 'hallucination', 'tool-use', 'verification'] },
  { id: 'ai-engineer-ai-agents-l4-018', language: 'ai-engineer', level: 'level4', category: 'AI Agents & Tool Use', subcategory: 'Computer Use', question: 'What is the "computer use" paradigm for AI agents and how does it differ from API-based tool use?', options: ['Computer use and API-based tools are identical', 'Computer use agents interact with applications through their GUI (screenshots → LLM decides where to click/type) rather than through programmatic APIs. This enables agents to use any application a human can use without dedicated API integrations. Trade-offs: much slower than API calls (screenshot processing + multiple interactions per action), less reliable (UI changes break agents), but infinitely more general (works with any application, including legacy software without APIs)', 'Computer use agents are always more reliable than API-based agents', 'Computer use only works with web applications'], correctAnswer: 1, explanation: 'Computer use (Claude Computer Use, OpenAI Operator): Agent sees a screenshot → identifies UI elements → outputs coordinates or actions (click, type, scroll) → environment executes → new screenshot → repeat. Benefits: (1) universal: works with any desktop/web app, (2) no API integration needed, (3) handles complex multi-app workflows (copy from spreadsheet → paste in email). Challenges: (1) slow: 1-5 seconds per action (screenshot + LLM inference), (2) fragile: UI redesigns break the agent, (3) error accumulation: small misclicks compound, (4) security: agent has full desktop access. Best practice: use API tools when available (fast, reliable), fall back to computer use for applications without APIs. Combine: API for data retrieval, GUI for actions in legacy apps.', tags: ['computer-use', 'gui-agents', 'screenshot', 'universal-agents'] },
  { id: 'ai-engineer-ai-agents-l4-019', language: 'ai-engineer', level: 'level4', category: 'AI Agents & Tool Use', subcategory: 'Streaming', question: 'How do streaming responses work with tool-calling agents and why are they important for user experience?', options: ['Streaming agent responses involves: (1) streaming the LLM\'s reasoning text as it generates, (2) detecting tool call requests in the stream, (3) pausing the stream to execute the tool, (4) streaming the tool execution status to the user, (5) resuming LLM generation with tool results. This provides continuous feedback (users see thinking/progress), reduces perceived latency, and enables early cancellation if the agent takes a wrong approach', 'Streaming is incompatible with tool-calling agents', 'Streaming adds no value to agent interactions', 'Users prefer waiting for complete responses over streaming'], correctAnswer: 0, explanation: 'Without streaming: user waits 30-60 seconds with no feedback → frustrating, appears frozen. With streaming: user sees "Thinking... I need to search for flight prices" → "Searching flights..." → "Found 3 options, comparing..." → final answer. Implementation: (1) LLM streams tokens, (2) parser detects tool_call JSON in stream, (3) yield status event "Executing search...", (4) run tool, (5) feed result back, (6) LLM continues streaming. Server-Sent Events (SSE) or WebSocket transport the stream to the client. Frameworks: LangChain astream_events, Vercel AI SDK useChat with tool results. UX considerations: show tool invocations as collapsible cards, animate thinking indicators, allow user to interrupt/redirect mid-stream.', tags: ['streaming', 'user-experience', 'sse', 'progressive-response'] },
  { id: 'ai-engineer-ai-agents-l4-020', language: 'ai-engineer', level: 'level4', category: 'AI Agents & Tool Use', subcategory: 'Guardrails', question: 'What permission models should be enforced for agent tool access?', options: ['Agents should have unrestricted access to all tools', 'Agent tool access should follow the principle of least privilege: (1) read-only tools (search, lookup) available by default, (2) write tools (create, update, delete) require explicit user permission per action or per session, (3) sensitive tools (payment, email sending) require per-invocation approval, (4) tool access scoped by user permissions (agent can only access what the user can access), (5) rate limits on expensive or irreversible actions. This prevents agents from taking harmful actions while maintaining usefulness', 'Tool permissions are unnecessary for internal-use agents', 'Per-invocation approval for every tool is the best practice'], correctAnswer: 1, explanation: 'Permission tiers: Tier 1 (auto-approved): read-only operations (search, query database, check status). Tier 2 (session-approved): user approves once for a class of actions ("Yes, you can send emails on my behalf during this session"). Tier 3 (per-action-approved): each invocation needs approval ("Send this email to john@example.com? [Approve/Deny]"). Tier 4 (forbidden): never available to the agent (delete account, transfer large amounts). Implementation: middleware layer between agent and tools that checks permissions, logs all tool invocations, and enforces rate limits. Audit trail: every tool call logged with: user, agent, tool, parameters, result, approval status. Critical for compliance (SOC2, GDPR) and debugging.', tags: ['permissions', 'least-privilege', 'access-control', 'audit-trail'] },
  { id: 'ai-engineer-ai-agents-l4-021', language: 'ai-engineer', level: 'level4', category: 'AI Agents & Tool Use', subcategory: 'Benchmarking', question: 'What does the SWE-bench benchmark measure and why is it a good test for coding agents?', options: ['SWE-bench measures general language understanding', 'All coding agents achieve >90% on SWE-bench', 'SWE-bench only tests simple function-level coding', 'SWE-bench evaluates whether an agent can resolve real GitHub issues from popular open-source Python repositories. The agent receives: a repository, an issue description, and must produce a patch that passes the repository\'s test suite. This tests: code understanding, bug localization across large codebases, code generation, and test-driven validation. It is uniquely challenging because it requires navigating real-world codebases with complex dependencies, not isolated coding puzzles'], correctAnswer: 3, explanation: 'SWE-bench (Jimenez et al. 2024): 2,294 real issues from 12 Python repos (Django, Flask, scikit-learn, etc.). For each issue: agent gets the repo at the commit before the fix + issue description → must produce a git patch. Evaluation: apply patch, run relevant tests. SWE-bench Lite: 300 curated issues. Current SOTA: ~50% on Lite (as of early 2025). Challenges: (1) repos have 100K+ lines — agent must localize the bug, (2) understanding test failures requires domain knowledge, (3) patches must be syntactically correct, pass linting, and not break other tests. This benchmarks real software engineering ability: reading code, understanding architecture, writing correct fixes, and test awareness.', tags: ['swe-bench', 'coding-agents', 'benchmark', 'software-engineering'] },
  { id: 'ai-engineer-ai-agents-l4-022', language: 'ai-engineer', level: 'level4', category: 'AI Agents & Tool Use', subcategory: 'Tool Creation', question: 'How can agents dynamically create and modify their own tools?', options: ['Tool creation requires restarting the agent system', 'Agents can only use pre-defined tools', 'Dynamically created tools are always more reliable than predefined tools', 'Agents can generate new tool functions as Python code, register them in their tool set, and use them in subsequent steps. This is useful when: (1) a task requires a specialized computation not in existing tools, (2) a common multi-tool pattern should be abstracted into a single tool for efficiency, (3) the agent needs to adapt to new APIs at runtime. The generated tools need validation (syntax check, sandboxed test execution) before being registered to prevent errors and security issues'], correctAnswer: 3, explanation: 'Dynamic tool creation: agent encounters a recurring pattern (convert temperature from C to F in multiple steps) → generates: def celsius_to_fahrenheit(temp_c: float) -> float: return temp_c * 9/5 + 32 → validates by executing test cases → registers as a new tool. More advanced: agent encounters a new API → reads documentation → generates a tool wrapper function with proper error handling → tests it → adds to toolkit. Voyager (Wang et al. 2023): Minecraft agent creates new skills (JavaScript functions) and stores them in a skill library, retrieving relevant skills for future tasks. Safety: validate generated code in sandbox, limit imports, review before registration in production systems.', tags: ['tool-creation', 'dynamic-tools', 'voyager', 'self-improvement'] },
  { id: 'ai-engineer-ai-agents-l4-023', language: 'ai-engineer', level: 'level4', category: 'AI Agents & Tool Use', subcategory: 'Delegation', question: 'What is the "agent-as-tool" pattern and when should agents delegate to sub-agents?', options: ['The agent-as-tool pattern always increases latency without benefit', 'Agents should never delegate to other agents', 'Sub-agents always share the same context as the parent agent', 'The agent-as-tool pattern wraps a specialized agent as a callable tool for a parent agent. The parent handles high-level orchestration while sub-agents handle domain-specific tasks (e.g., a research agent calls a coding sub-agent and a search sub-agent). Delegation is beneficial when: sub-tasks require different system prompts, tools, or models; sub-tasks can run in parallel; or the task decomposition is clear. Each sub-agent has its own context window, preventing context pollution'], correctAnswer: 3, explanation: 'Agent-as-tool: parent_agent has tools = [search_agent, code_agent, data_agent]. Each sub-agent: (1) has specialized system prompt and tool set, (2) runs in its own context (fresh conversation), (3) returns structured result to parent. Benefits: (a) modularity: update code_agent without touching parent, (b) parallel execution: search_agent and data_agent can run simultaneously, (c) context isolation: code agent doesn\'t need search history, (d) different models: use GPT-4o for reasoning parent, Claude for code sub-agent. Implementation in LangGraph: sub-agents as subgraphs invoked from the main graph. OpenAI Swarm: agents hand off to other agents with context transfer. Key: define clear input/output interfaces for each sub-agent.', tags: ['agent-as-tool', 'delegation', 'sub-agents', 'composition'] },
  { id: 'ai-engineer-ai-agents-l4-024', language: 'ai-engineer', level: 'level4', category: 'AI Agents & Tool Use', subcategory: 'Observability', question: 'What should an agent observability system track and how does it differ from standard LLM observability?', options: ['Observability adds too much overhead for production agents', 'Agent observability only needs to track final outputs', 'Standard LLM logging is sufficient for agent systems', 'Agent observability must track: (1) full trajectory (sequence of thoughts, tool calls, observations), (2) decision points (why this tool and not that one?), (3) state transitions in the state machine, (4) tool latency and success rates per tool, (5) cost per task (not just per call), (6) loop detection (same action repeated), (7) branching paths in multi-agent systems. This requires distributed tracing across LLM calls, tool executions, and sub-agent invocations, with correlation IDs linking all steps of a single task'], correctAnswer: 3, explanation: 'Agent trace structure: Task_ID → [Step_1: {thought: "...", action: search(query="..."), observation: "...", tokens: 1500, latency: 2.3s, model: "gpt-4o"}, Step_2: {...}, ...]. Aggregate metrics: task_success_rate, avg_steps_per_task, avg_cost_per_task, tool_error_rate, timeout_rate. Tools: LangSmith (LangChain native), Langfuse (open source), Arize Phoenix (open source). Key features needed: (1) visual trajectory replay (step-by-step what the agent did), (2) filtering by outcome (show all failed trajectories), (3) cost attribution (which steps are expensive?), (4) comparison (trajectory of successful vs failed attempts on same query). Production alert examples: "agent averaging >20 steps per task (normally 8)" → investigate infinite loops or task decomposition failures.', tags: ['agent-observability', 'tracing', 'trajectory', 'langsmith'] },
  { id: 'ai-engineer-ai-agents-l4-025', language: 'ai-engineer', level: 'level4', category: 'AI Agents & Tool Use', subcategory: 'Reliability', question: 'What is the reliability gap between agent benchmarks and production performance, and how can it be addressed?', options: ['Benchmark environments are clean and predictable while production environments have: noisy inputs (typos, ambiguous queries), unreliable tools (APIs timeout, return errors), adversarial users (prompt injection, edge cases), and distribution shift (queries unlike training data). Addressing the gap requires: extensive error handling, fallback strategies, input validation, output verification, comprehensive logging for debugging, and continuous evaluation on production-sampled queries rather than relying solely on benchmark scores', 'Production agents always outperform benchmark results', 'The reliability gap cannot be reduced', 'Agent benchmark performance directly translates to production'], correctAnswer: 0, explanation: 'Common production failures not in benchmarks: (1) user provides partial/ambiguous information → agent makes wrong assumptions instead of asking for clarification, (2) API returns unexpected format → agent crashes or misinterprets, (3) user changes their mind mid-conversation → agent cannot adapt the plan, (4) agent\'s tool produces wrong result → agent doesn\'t verify and passes it through, (5) adversarial inputs trigger unexpected behavior. Mitigation: (a) input classification (is this query within the agent\'s capability?), (b) output verification (does the result make sense?), (c) regression testing on production failure cases, (d) canary deployment with human review, (e) graceful degradation (partial results better than crash). Treat agent reliability engineering like traditional software reliability: SLOs, error budgets, incident review.', tags: ['reliability', 'production-gap', 'error-handling', 'graceful-degradation'] },
  { id: 'ai-engineer-ai-agents-l4-026', language: 'ai-engineer', level: 'level4', category: 'AI Agents & Tool Use', subcategory: 'Parallel Execution', question: 'When can agent steps be parallelized and what coordination is required?', options: ['Parallelization always improves agent performance', 'Agent steps can be parallelized when they are independent (no data dependency between them). Examples: searching multiple sources simultaneously, fetching different user data in parallel, running multiple analyses on the same data. Coordination requires: (1) a map-reduce pattern (fan out → collect results → synthesize), (2) handling partial failures (some parallel tasks fail while others succeed), (3) combining results from different tools coherently. LangGraph supports parallel execution via fan-out nodes with a join/reduce node', 'Only API calls can be parallelized, not LLM reasoning steps', 'Agent steps must always execute sequentially'], correctAnswer: 1, explanation: 'Parallelizable patterns: (1) Multi-source search: search Google + search internal docs + search Slack simultaneously → merge results, (2) Data gathering: fetch user profile + fetch order history + fetch preferences in parallel → combine into context, (3) Multi-perspective analysis: analyze document for legal issues AND financial issues AND compliance issues in parallel. Coordination: LangGraph fan-out: single node sends state to multiple parallel branches → each branch processes independently → join node collects all results and merges into state. Failure handling: if 2/3 parallel searches succeed, use those results and note the failed source. Timeout: if a parallel branch takes too long, proceed with available results. Key: identify independent steps in the plan → execute in parallel → 2-5x speedup on multi-step tasks.', tags: ['parallel-execution', 'fan-out', 'map-reduce', 'concurrency'] },
  { id: 'ai-engineer-ai-agents-l4-027', language: 'ai-engineer', level: 'level4', category: 'AI Agents & Tool Use', subcategory: 'Agentic RAG', question: 'How does agentic RAG differ from simple retrieve-and-generate RAG?', options: ['Agentic RAG gives the agent control over the retrieval process: it can decide when to retrieve, what to retrieve, reformulate queries based on initial results, retrieve from multiple sources, and decide when it has sufficient information to answer. Unlike simple RAG (one-shot retrieve→generate), agentic RAG can iteratively refine its search, backtrack when results are insufficient, and combine information from multiple retrieval steps before generating the final answer', 'Agentic RAG is always slower with no quality improvement', 'Agentic RAG and simple RAG are identical', 'Simple RAG always retrieves sufficient information in one pass'], correctAnswer: 0, explanation: 'Simple RAG: user query → embed → retrieve top-5 → generate answer. Fails when: (1) query is ambiguous (need to decompose), (2) first retrieval misses relevant docs (need reformulation), (3) answer requires information from multiple sources (need iterative retrieval). Agentic RAG: (1) Analyze query → decide if retrieval is needed, (2) Decompose into sub-queries if complex, (3) Retrieve for each sub-query, (4) Evaluate retrieved context — sufficient? If not, reformulate and retrieve again, (5) Synthesize answer from all retrieved context. Self-RAG (Asai et al. 2023): model generates retrieval tokens indicating when to retrieve and reflection tokens evaluating retrieval quality. CRAG (Corrective RAG): retrieves → evaluates relevance → if low relevance, rewrites query and retrieves again.', tags: ['agentic-rag', 'iterative-retrieval', 'self-rag', 'adaptive'] },
  { id: 'ai-engineer-ai-agents-l4-028', language: 'ai-engineer', level: 'level4', category: 'AI Agents & Tool Use', subcategory: 'Testing', question: 'How should agent systems be tested before production deployment?', options: ['Only end-to-end tests are needed for agents', 'Manual testing of a few examples is sufficient', 'Agent testing should include: (1) unit tests for individual tools (correct parameters → correct results), (2) trajectory tests with golden paths (given this input, the agent should call these tools in this order), (3) adversarial tests (prompt injection, ambiguous inputs, tool failures), (4) end-to-end tests with mocked tools (verify task completion), (5) regression tests from production failures, (6) cost and latency benchmarks. Use deterministic settings (temperature=0) for reproducible testing and evaluate on diverse, representative task distributions', 'Agent systems cannot be tested automatically'], correctAnswer: 2, explanation: 'Agent testing pyramid: (1) Tool unit tests: mock API responses, verify tool functions handle edge cases (empty results, errors, large payloads), (2) Agent unit tests: given a specific state + observation, verify the agent makes the correct decision (tool selection, parameter values), (3) Trajectory tests: record golden trajectories from known-good executions, verify new agent versions follow similar paths, (4) Integration tests: run agent end-to-end with mocked external services, verify task completion, (5) Adversarial tests: prompt injection attempts, invalid inputs, confusing multi-step requests. Frameworks: AgentEval, custom pytest fixtures with LLM-as-Judge for evaluating open-ended responses. CI pipeline: run trajectory + integration tests on every code change, full adversarial suite weekly.', tags: ['agent-testing', 'trajectory-tests', 'adversarial', 'ci-pipeline'] },
  { id: 'ai-engineer-ai-agents-l4-029', language: 'ai-engineer', level: 'level4', category: 'AI Agents & Tool Use', subcategory: 'Context Window', question: 'How should agents manage their context window as conversations grow long?', options: ['Context window limits have been eliminated by modern models', 'All conversation history should always be included in the context', 'Even with large context windows, agents should actively manage context because: (1) performance degrades with irrelevant context (lost in the middle), (2) cost scales linearly with tokens, (3) latency increases with context length. Strategies: summarize completed steps into concise results, remove raw tool outputs after extracting key information, maintain a separate working memory of key facts, and use retrieval over past conversation for relevant history rather than including everything', 'Context window management is unnecessary with 128K+ context models'], correctAnswer: 2, explanation: 'Context management for agents: (1) Rolling summary: after every 5 steps, summarize completed steps → replace detailed history with 200-token summary, (2) Tool output pruning: keep the first 500 tokens of each tool result + extracted key facts, discard raw output, (3) Working memory: maintain a structured "scratchpad" of key facts separate from conversation (updated explicitly), (4) Retrieval-based history: for very long interactions, embed all past turns → retrieve relevant ones for current step instead of including all. Example: 50-step agent interaction. Naive: 50 steps × 2K tokens/step = 100K tokens (expensive, slow). Managed: current state (500t) + last 3 steps (6K) + relevant history retrieval (2K) + tools (3K) = ~12K tokens. Quality is similar because most past steps are irrelevant to current decision.', tags: ['context-management', 'summarization', 'working-memory', 'token-efficiency'] },
  { id: 'ai-engineer-ai-agents-l4-030', language: 'ai-engineer', level: 'level4', category: 'AI Agents & Tool Use', subcategory: 'Safety', question: 'What is the "inner alignment" problem for AI agents?', options: ['Agents always follow their system prompts exactly', 'Inner alignment asks whether the agent\'s learned objectives match the intended objectives specified in its instructions. Even with clear system prompts, an agent might pursue proxy goals (maximize tool calls instead of solving the problem) or find reward hacks (appearing helpful without being genuinely useful). In practice: agents may take shortcuts that satisfy surface-level evaluation criteria while violating the spirit of the task. Mitigation requires outcome-based evaluation, diverse test cases, and regular human review of agent behavior', 'Inner alignment only concerns superintelligent AI systems', 'Inner alignment is a solved problem with current RLHF techniques'], correctAnswer: 1, explanation: 'Practical inner alignment issues in current agents: (1) sycophancy: agent agrees with user\'s incorrect assumptions instead of correcting them, (2) sandbagging: agent provides minimal effort when not being evaluated, (3) specification gaming: agent finds a shortcut that passes automated checks but doesn\'t actually solve the problem (e.g., generating code that passes tests but has hardcoded answers), (4) deceptive compliance: appearing to follow safety guidelines while finding workarounds. Current mitigations: (a) diverse evaluation beyond simple pass/fail, (b) red-teaming: adversarial testing of agent behavior, (c) behavioral evaluations (does the agent flag its own uncertainty honestly?), (d) monitoring for suspicious patterns in agent trajectories (unusually fast completion, repetitive strategies).', tags: ['inner-alignment', 'specification-gaming', 'sycophancy', 'agent-safety'] },
  { id: 'ai-engineer-ai-agents-l4-031', language: 'ai-engineer', level: 'level4', category: 'AI Agents & Tool Use', subcategory: 'Deployment', question: 'What architecture patterns support deploying agents at scale in production?', options: ['Production agent deployment patterns: (1) async task queue: user submits request → agent runs asynchronously → notifies user when complete (handles long-running tasks), (2) event-driven: agent steps are triggered by events (tool completion, user input, timer), (3) serverless: each agent step runs as a separate function invocation with state in durable storage (cost-effective for bursty workloads), (4) persistent workers: long-running agent processes with in-memory state (lowest latency). Choice depends on task duration, concurrency requirements, and cost constraints', 'Agents should always run as a single synchronous service', 'Deploying agents requires no special infrastructure considerations', 'Production agents must always respond within 1 second'], correctAnswer: 0, explanation: 'Architecture options: (1) Synchronous: user waits while agent runs. OK for <30s tasks. FastAPI + streaming response. (2) Async queue: user gets task_id → polls or receives webhook. Celery/Redis/SQS queue → worker runs agent → stores result. Good for 1-60 min tasks. (3) Event-driven (Temporal/Inngest): each step is a durable activity. Agent state persisted to database. Can survive process restarts, handle retries. (4) Serverless (AWS Lambda + Step Functions): each LLM call/tool call is a Lambda invocation, state in DynamoDB. Pay-per-use, auto-scales. Latency: 100ms cold start. Scaling: multiple agent instances handle concurrent users. State persistence: Redis for fast access, Postgres for durability. Rate limiting: per-user concurrency limits to prevent resource exhaustion.', tags: ['deployment', 'async', 'event-driven', 'serverless'] },
  { id: 'ai-engineer-ai-agents-l4-032', language: 'ai-engineer', level: 'level4', category: 'AI Agents & Tool Use', subcategory: 'Knowledge', question: 'How do agents effectively use structured knowledge (databases, knowledge graphs) versus unstructured knowledge (documents)?', options: ['Text-to-SQL works perfectly without any errors', 'Structured knowledge (SQL databases, knowledge graphs) provides exact answers to specific queries (revenue for Q3, employee count) through text-to-SQL or SPARQL generation. Unstructured knowledge (documents, wikis) provides contextual understanding through RAG. Effective agents combine both: use structured queries for factual data and RAG for procedural knowledge, policies, and context. The agent decides which knowledge source to query based on the question type', 'RAG is always sufficient; databases are unnecessary for agents', 'Agents should only use one type of knowledge source'], correctAnswer: 1, explanation: 'Structured (database): "What was revenue last quarter?" → agent generates SQL → executes → exact number. Strengths: precise, aggregatable, always up-to-date. Weaknesses: requires schema understanding, SQL generation can be wrong, limited to what\'s in the DB. Unstructured (RAG): "What is our return policy?" → retrieves from policy documents → answers. Strengths: handles nuanced, procedural, qualitative information. Weaknesses: retrieval noise, context limits. Combined agent: classify query → factual/quantitative → SQL agent, procedural/qualitative → RAG agent, hybrid → both + synthesis. Text-to-SQL agents: generate SQL → explain intent → execute → validate results make sense → return. Error handling: if SQL fails, try rephrasing; if results seem wrong (negative revenue), flag for verification.', tags: ['structured-knowledge', 'text-to-sql', 'knowledge-graph', 'hybrid-knowledge'] },
  { id: 'ai-engineer-ai-agents-l4-033', language: 'ai-engineer', level: 'level4', category: 'AI Agents & Tool Use', subcategory: 'Evaluation Frameworks', question: 'What is the GAIA benchmark and what does it reveal about current agent capabilities?', options: ['Current agents have surpassed human performance on GAIA', 'GAIA only evaluates coding abilities', 'GAIA (General AI Assistants) tests agents on real-world tasks requiring multiple steps: web browsing, file processing, calculation, and reasoning. Tasks are graded by difficulty (Level 1-3). Key insight: humans achieve ~92% accuracy while the best agents achieve ~70% on Level 1, ~50% on Level 2, and ~30% on Level 3 tasks. This reveals that current agents struggle with: multi-step reasoning chains, recovering from errors, and combining information from multiple modalities and sources', 'GAIA only tests simple question-answering'], correctAnswer: 2, explanation: 'GAIA (Mialon et al. 2023): 466 tasks requiring tools + reasoning. Example Level 1: "What is the population of the capital of the country where the Eiffel Tower is located?" (chain: Eiffel Tower → France → Paris → population). Level 3: "Download this CSV, calculate the Gini coefficient, compare it with the WHO data for 2020, and explain the discrepancy." Human accuracy: ~92% across levels. Best agents (GPT-4 + tools): Level 1 ~70%, Level 2 ~50%, Level 3 ~30%. Failure analysis: (1) error compounding: one wrong step derails everything, (2) tool misuse: wrong parameters or wrong tool selection, (3) premature answers: generating answer before gathering sufficient information, (4) inability to backtrack when a reasoning path fails. GAIA provides a realistic benchmark for end-to-end agent capability.', tags: ['gaia', 'benchmark', 'agent-capabilities', 'multi-step'] },
];

export default questions;
